tests:
from solution import add
def test_add():
    assert add(1, 2) == 3
def test_neg():
    assert add(-1, 1) == 0

from solution import is_even
def test_even():
    assert is_even(4)
def test_odd():
    assert not is_even(3)

from solution import reverse
def test_rev():
    assert reverse('abc') == 'cba'
def test_empty():
    assert reverse('') == ''

from solution import evaluate
def test_simple():
    assert evaluate('2+3*4') == 14
def test_paren():
    assert evaluate('(1+2)*3') == 9
